        marks = [r for r in range(h) if grid[r][c] != 0]
        if not marks:
            continue
        # Fill above the first mark with its color.
        for r in range(marks[0]):
            out[r][c] = grid[marks[0]][c]
        # In each gap, extend the lower mark upward to the previous mark.
        for upper, lower in zip(marks, marks[1:]):
            color = grid[lower][c]
            for r in range(upper + 1, lower):
                out[r][c] = color
        # Fill below the last mark (normally none; bottom marker is a 5).
        for r in range(marks[-1] + 1, h):
            out[r][c] = grid[marks[-1]][c]
    return out
